-- origin=auto row_preserving=True check=rows_equal
CREATE VIEW v_satscores AS SELECT satscores.cds AS cds, satscores.rtype AS rtype, satscores.sname AS sname, satscores.dname AS dname, satscores.cname AS cname, satscores.enroll12 AS enroll12, satscores.NumTstTakr AS NumTstTakr, satscores.AvgScrRead AS AvgScrRead, satscores.AvgScrMath AS AvgScrMath, satscores.AvgScrWrite AS AvgScrWrite, satscores.NumGE1500 AS NumGE1500, cds.NCESDist AS cds_NCESDist, cds.NCESSchool AS cds_NCESSchool, cds.StatusType AS cds_StatusType, cds.County AS cds_County, cds.District AS cds_District, cds.School AS cds_School, cds.Street AS cds_Street, cds.StreetAbr AS cds_StreetAbr, cds.City AS cds_City, cds.Zip AS cds_Zip, cds.State AS cds_State, cds.MailStreet AS cds_MailStreet, cds.MailStrAbr AS cds_MailStrAbr, cds.MailCity AS cds_MailCity, cds.MailZip AS cds_MailZip, cds.MailState AS cds_MailState, cds.Phone AS cds_Phone, cds.Ext AS cds_Ext, cds.Website AS cds_Website, cds.OpenDate AS cds_OpenDate, cds.ClosedDate AS cds_ClosedDate, cds.Charter AS cds_Charter, cds.CharterNum AS cds_CharterNum, cds.FundingType AS cds_FundingType, cds.DOC AS cds_DOC, cds.DOCType AS cds_DOCType, cds.SOC AS cds_SOC, cds.SOCType AS cds_SOCType, cds.EdOpsCode AS cds_EdOpsCode, cds.EdOpsName AS cds_EdOpsName, cds.EILCode AS cds_EILCode, cds.EILName AS cds_EILName, cds.GSoffered AS cds_GSoffered, cds.GSserved AS cds_GSserved, cds.Virtual AS cds_Virtual, cds.Magnet AS cds_Magnet, cds.Latitude AS cds_Latitude, cds.Longitude AS cds_Longitude, cds.AdmFName1 AS cds_AdmFName1, cds.AdmLName1 AS cds_AdmLName1, cds.AdmEmail1 AS cds_AdmEmail1, cds.AdmFName2 AS cds_AdmFName2, cds.AdmLName2 AS cds_AdmLName2, cds.AdmEmail2 AS cds_AdmEmail2, cds.AdmFName3 AS cds_AdmFName3, cds.AdmLName3 AS cds_AdmLName3, cds.AdmEmail3 AS cds_AdmEmail3, cds.LastUpdate AS cds_LastUpdate FROM satscores LEFT JOIN schools AS cds ON satscores.cds = cds.CDSCode;
